// big-endian addition: reverse, add little-endian, reverse back.
pub trait Add<R> {
    type O;
}
impl<L, R> Add<R> for L
where
    L: RevA<End>,
    R: RevA<End>,
    <L as RevA<End>>::O: AddC<<R as RevA<End>>::O, C0>,
    <<L as RevA<End>>::O as AddC<<R as RevA<End>>::O, C0>>::O: RevA<End>,
{
    type O = <<<L as RevA<End>>::O as AddC<<R as RevA<End>>::O, C0>>::O as RevA<End>>::O;
}

// big-endian value read, through the reversal
pub trait Val {
    const V: u32;
}
impl<X: RevA<End>> Val for X
where
    <X as RevA<End>>::O: Dec,
{
    const V: u32 = <<X as RevA<End>>::O as Dec>::V;
}

