// ---- the a133 ladder, running on the binary form ----
pub struct Z;
pub struct S<T>(PhantomData<T>);
pub trait Bump {
    type O;
}
impl Bump for Z {
    type O = Z;
}
impl<T> Bump for S<T> {
    type O = S<S<T>>;
}
pub trait Len {
    type L;
}
impl Len for BEnd {
    type L = Z;
}
impl<T: Len> Len for Z0<T>
where
    T::L: Bump,
{
    type L = <T::L as Bump>::O;
}
impl<T: Len> Len for Z1<T> {
    type L = S<T::L>;
}

#[derive(Copy, Clone, Default)]
pub struct WideNil;
pub trait Rung {
    type T: Copy;
}
type L0 = Z;
type L1 = S<L0>;
type L2 = S<L1>;
type L3 = S<L2>;
type L4 = S<L3>;
type L5 = S<L4>;
type L6 = S<L5>;
type L7 = S<L6>;
impl Rung for L0 {
    type T = u8;
}
impl Rung for L1 {
    type T = u8;
}
impl Rung for L2 {
    type T = u8;
}
impl Rung for L3 {
    type T = u8;
}
impl Rung for L4 {
    type T = u16;
}
impl Rung for L5 {
    type T = u32;
}
impl Rung for L6 {
    type T = u64;
}
impl Rung for L7 {
    type T = u128;
}
impl<T> Rung for S<S<S<S<S<S<S<S<T>>>>>>>> {
    type T = WideNil;
}

pub struct Hot;
// X is a BIG-ENDIAN decimal magnitude. Reverse, convert to binary, decrement,
// count digits, pick the rung. Every step is trait resolution.
pub trait Store<X> {
    type T: Copy;
}
impl<X: RevA<End>> Store<X> for Hot
where
    <X as RevA<End>>::O: ToBin,
    <<X as RevA<End>>::O as ToBin>::B: BDec,
    <<<X as RevA<End>>::O as ToBin>::B as BDec>::O: Len,
    <<<<X as RevA<End>>::O as ToBin>::B as BDec>::O as Len>::L: Rung,
{
    type T = <<<<<X as RevA<End>>::O as ToBin>::B as BDec>::O as Len>::L as Rung>::T;
}

pub struct Fixed<I, F, S>(pub <S as Store<<I as Add<F>>::O>>::T, PhantomData<(I, F)>)
where
    I: Add<F>,
    S: Store<<I as Add<F>>::O>;

pub type BIG = N1<N0<N0<N0<N0<End>>>>>;
const _: () = assert!(<BIG as Val>::V == 10000);
pub type Z0T = N0<End>;
pub fn big(x: Fixed<BIG, Z0T, Hot>) -> WideNil {
    x.0
}
